        elif m == 'Log.entryAdded' and e['params']['entry']['level'] in ('error',): out.append('LOG ' + e['params']['entry']['text'][:200] + ' ' + e['params']['entry'].get('url', ''))
    ws.events.clear(); return out
def size(w, h): ws.call('Emulation.setDeviceMetricsOverride', width=w, height=h, deviceScaleFactor=1, mobile=w < 600)
def nav(url, wait=2.5):
