def ev(expr):
    r = ws.call('Runtime.evaluate', expression=expr, returnByValue=True, awaitPromise=True)
    if 'exceptionDetails' in r: return 'ERR ' + str(r['exceptionDetails'].get('exception', {}).get('description'))
    return r['result'].get('value')
def shot(name):
