import socket, base64, os, json, struct, sys, subprocess, time, urllib.request
class WS:
    def __init__(s, url):
        u = url[len('ws://'):]; hp, path = u.split('/',1); h,p = hp.split(':')
        s.s = socket.create_connection((h,int(p)))
        k = base64.b64encode(os.urandom(16)).decode()
        s.s.sendall(f"GET /{path} HTTP/1.1\r\nHost: {hp}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key​: {k}\r\nSec-WebSocket-Version: 13\r\n\r\n".encode())
        b=b''
        while b'\r\n\r\n' not in b: b+=s.s.recv(1)
        s.id=0; s.events=[]
    def send(s, obj):
        d=json.dumps(obj).encode(); m=os.urandom(4); n=len(d)
        hdr=bytes([0x81]) + (bytes([0x80|n]) if n<126 else bytes([0x80|126])+struct.pack('>H',n) if n<65536 else bytes([0x80|127])+struct.pack('>Q',n))
        s.s.sendall(hdr+m+bytes(c^m[i%4] for i,c in enumerate(d)))
    def rx(s,n):
        b=b''
        while len(b)<n: b+=s.s.recv(n-len(b))
        return b
    def recv(s):
        buf=b''
        while True:
            h=s.rx(2); fin=h[0]&0x80; n=h[1]&0x7f
            if n==126: n=struct.unpack('>H',s.rx(2))[0]
            elif n==127: n=struct.unpack('>Q',s.rx(8))[0]
            buf+=s.rx(n)
            if fin: return json.loads(buf)
    def call(s, method, **params):
